-- ============================================================
-- 41_part1 of 2 - Estimates Tracker import. Run part1 then part2.
-- Each part re-declares the columns so order/reruns are safe.
-- ============================================================

alter table estimates add column if not exists stage           text;
alter table estimates add column if not exists pipeline_status text;
alter table estimates add column if not exists requested_date  date;
alter table estimates add column if not exists monday_id       text;
drop index if exists estimates_monday_id_key;
create unique index estimates_monday_id_key on estimates (monday_id);

